      ]
    },
    "Merchandising": {
      "objects": [
        "Museum Store Manager",
        "Merchandise Item",
        "Exhibit",
        "Sales Trends Review"
      ]
    },
    "Scheduling": {
      "objects": [
        "Museum Coordinator",
        "Museum Schedule",
        "Exhibit",
